//! Shared data model. Game data is generated by the `planner-import` tool into
//! `data/<game>.json`; factories and worlds are edited in the app and saved as
//! JSON under `factories/<game>/`. Field names match the JSON files.
//!
//! Units: every rate the engine reports is per minute. Recipe stack amounts
//! are per cycle; fluids are in m³ (Satisfactory) or fluid units (Factorio).

use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::sync::{Mutex, OnceLock};

/// Pseudo-item for electricity. Generators produce it; machines consume it.
pub const POWER: &str = "@power";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum GameId {
    Satisfactory,
    Factorio,
    Dsp,
}

impl GameId {
    pub const ALL: [GameId; 3] = [GameId::Satisfactory, GameId::Factorio, GameId::Dsp];

    pub fn key(self) -> &'static str {
        match self {
            GameId::Satisfactory => "satisfactory",
            GameId::Factorio => "factorio",
            GameId::Dsp => "dsp",
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            GameId::Satisfactory => "Satisfactory",
            GameId::Factorio => "Factorio",
            GameId::Dsp => "Dyson Sphere Program",
        }
    }

    pub fn from_key(key: &str) -> Option<GameId> {
        GameId::ALL.into_iter().find(|g| g.key() == key)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Form {
    Solid,
    Liquid,
    Gas,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Item {
    pub id: String,
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub form: Option<Form>,
    /// Mined or pumped, never crafted from other items in normal play.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub raw: bool,
    /// Default recipe for this item in target mode.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recipe: Option<String>,
    /// Fuel value in MJ per item (per m³ for fluids).
    #[serde(default, rename = "energyMJ", skip_serializing_if = "Option::is_none")]
    pub energy_mj: Option<f64>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Building {
    pub id: String,
    pub name: String,
    /// Draw in MW at 100% clock / speed 1, before sloops or modules.
    #[serde(rename = "powerMW")]
    pub power_mw: f64,
    /// Satisfactory: power scales by clock^exponent. Absent = linear.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub power_exponent: Option<f64>,
    /// Crafting speed multiplier (Factorio, DSP). Default 1.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub speed: Option<f64>,
    /// Built-in productivity bonus, e.g. 0.5 for +50% (Factorio foundry).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub base_productivity: Option<f64>,
    /// Satisfactory production-amplifier (somersloop) slots.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sloop_slots: Option<u32>,
    /// Floor area per machine: m² (Satisfactory) or tiles (Factorio).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub footprint: Option<f64>,
    /// Factorio crafting categories this machine accepts.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub categories: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub module_slots: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Stack {
    pub item: String,
    pub amount: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct PowerRange {
    pub min: f64,
    pub max: f64,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Recipe {
    pub id: String,
    pub name: String,
    /// Seconds per cycle at speed 1 / 100% clock.
    pub time: f64,
    pub inputs: Vec<Stack>,
    pub outputs: Vec<Stack>,
    /// Building ids able to run this recipe; the first is the default.
    pub buildings: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,
    /// Satisfactory alternate recipe (must be unlocked by hard drive).
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub alternate: bool,
    /// Variable-power recipes (particle accelerator etc.), MW at 100%.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub power: Option<PowerRange>,
    /// Generator recipe: MW produced per machine at 100% clock.
    #[serde(
        default,
        rename = "generatesMW",
        skip_serializing_if = "Option::is_none"
    )]
    pub generates_mw: Option<f64>,
    /// Factorio: productivity bonuses may apply.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub allow_productivity: bool,
    /// Factorio: per-output amount that productivity does not multiply.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ignored_by_productivity: Option<BTreeMap<String, f64>>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GameFeatures {
    pub clock: bool,
    pub sloops: bool,
    pub power: bool,
    pub productivity: bool,
    pub speed_bonus: bool,
    pub footprint: bool,
    /// Footprint unit label ("m²" or "tiles").
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub area_unit: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Skipped {
    pub id: String,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GameData {
    pub game: GameId,
    pub name: String,
    /// Where the data came from, e.g. the docs file path and game version.
    pub source: String,
    pub generated_at: String,
    pub items: BTreeMap<String, Item>,
    pub buildings: BTreeMap<String, Building>,
    pub recipes: BTreeMap<String, Recipe>,
    pub features: GameFeatures,
    /// Items imported by default (raw resources, water).
    pub default_imports: Vec<String>,
    /// Relative scarcity weights for raw items, used by the min-raw objective.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource_weights: Option<BTreeMap<String, f64>>,
    /// Importer notes: skipped records and why.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub skipped: Option<Vec<Skipped>>,
    /// Derived lookups, built on first use. Not saved.
    #[serde(skip)]
    pub cache: DataCache,
}

/// Lookups derived from game data. Cloning gives an empty cache.
#[derive(Debug, Default)]
pub struct DataCache {
    pub producers: OnceLock<BTreeMap<String, Vec<String>>>,
    pub producible: Mutex<HashMap<String, bool>>,
}

impl Clone for DataCache {
    fn clone(&self) -> Self {
        DataCache::default()
    }
}

impl PartialEq for DataCache {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

// ---------------------------------------------------------------------------
// Factory documents

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LineSettings {
    /// Satisfactory clock, 0.01–2.5 (1 = 100%).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub clock: Option<f64>,
    /// Somersloops slotted.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sloops: Option<u32>,
    /// Override the recipe's default building.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub building: Option<String>,
    /// Extra speed, 0.5 = +50% (modules, beacons, proliferator).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub speed_bonus: Option<f64>,
    /// Extra productivity, 0.25 = +25%.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prod_bonus: Option<f64>,
}

impl LineSettings {
    pub fn is_empty(&self) -> bool {
        *self == LineSettings::default()
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Line {
    pub id: String,
    pub recipe: String,
    #[serde(flatten)]
    pub settings: LineSettings,
    /// Locked machine count; None lets the solver size the line.
    #[serde(default)]
    pub machines: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum Objective {
    #[default]
    #[serde(rename = "min-raw")]
    MinRaw,
    #[serde(rename = "min-power")]
    MinPower,
    #[serde(rename = "min-machines")]
    MinMachines,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    /// The solver picks lines to meet targets.
    #[default]
    Target,
    /// You type the lines.
    Manual,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Target {
    pub item: String,
    pub rate: f64,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct FactoryImports {
    /// Items imported everywhere they are consumed.
    #[serde(default)]
    pub items: Vec<String>,
    /// Per-consumer imports, `item>lineId`.
    #[serde(default)]
    pub edges: Vec<String>,
    /// Default imports (raw items) the user wants produced instead.
    #[serde(default)]
    pub exclude: Vec<String>,
}

fn default_schema() -> u32 {
    1
}
fn default_spacing() -> f64 {
    4.0
}
fn untitled() -> String {
    "Untitled".into()
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Factory {
    #[serde(default = "default_schema")]
    pub schema: u32,
    pub id: String,
    pub game: GameId,
    #[serde(default = "untitled")]
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
    #[serde(default)]
    pub mode: Mode,
    #[serde(default)]
    pub objective: Objective,
    #[serde(default)]
    pub targets: Vec<Target>,
    /// Target mode: item -> recipe id chosen to make it.
    #[serde(default)]
    pub recipe_choice: BTreeMap<String, String>,
    /// Target mode: let the solver choose among all unlocked recipes.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub optimize: bool,
    /// Target mode: settings for the auto line of each recipe.
    #[serde(default)]
    pub line_settings: BTreeMap<String, LineSettings>,
    /// Manual lines, plus locked extra lines in target mode.
    #[serde(default)]
    pub lines: Vec<Line>,
    #[serde(default)]
    pub imports: FactoryImports,
    /// Floor spacing factor for foundation counts (Satisfactory).
    #[serde(default = "default_spacing")]
    pub spacing: f64,
    #[serde(default)]
    pub created_at: String,
    #[serde(default)]
    pub updated_at: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WorldEntry {
    pub factory: String,
    pub multiplier: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct World {
    #[serde(default = "default_schema")]
    pub schema: u32,
    pub id: String,
    pub game: GameId,
    #[serde(default = "untitled")]
    pub name: String,
    #[serde(default)]
    pub entries: Vec<WorldEntry>,
    #[serde(default)]
    pub created_at: String,
    #[serde(default)]
    pub updated_at: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GameSettings {
    /// Unlocked alternate recipe ids (Satisfactory).
    #[serde(default)]
    pub unlocked: Vec<String>,
    /// Factorio: preferred building per crafting category.
    #[serde(default)]
    pub default_building: BTreeMap<String, String>,
    /// Default spacing factor for new factories.
    #[serde(default = "default_spacing")]
    pub spacing: f64,
}

impl Default for GameSettings {
    fn default() -> Self {
        GameSettings {
            unlocked: vec![],
            default_building: BTreeMap::new(),
            spacing: 4.0,
        }
    }
}

// ---------------------------------------------------------------------------
// Solver output (not saved)

#[derive(Debug, Clone, PartialEq)]
pub struct PlanLine {
    pub id: String,
    pub recipe: String,
    pub building: String,
    pub machines: f64,
    pub locked: bool,
    /// Generated from targets rather than typed by the user.
    pub auto: bool,
    pub settings: LineSettings,
    /// Net per-minute flow of the whole line by item (+ produced, − consumed).
    pub rates: BTreeMap<String, f64>,
    /// MW drawn by the whole line (negative = generated).
    pub power_mw: f64,
    /// Floor area of the whole line, whole machines.
    pub footprint: f64,
}

impl PlanLine {
    pub fn rate(&self, item: &str) -> f64 {
        self.rates.get(item).copied().unwrap_or(0.0)
    }
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct PlanItem {
    pub item: String,
    pub produced: f64,
    pub consumed: f64,
    pub imported: f64,
    pub surplus: f64,
    pub target: f64,
    /// Demand the plan could not meet.
    pub unbalanced: f64,
}

/// Flow of one item from a source (line id or "import") to a consumer
/// (line id, "target" or "surplus").
#[derive(Debug, Clone, PartialEq)]
pub struct PlanEdge {
    pub item: String,
    pub from: String,
    pub to: String,
    pub rate: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PlanStatus {
    Ok,
    Unbalanced,
    Error,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Plan {
    pub status: PlanStatus,
    pub message: Option<String>,
    pub lines: Vec<PlanLine>,
    pub items: BTreeMap<String, PlanItem>,
    pub edges: Vec<PlanEdge>,
    /// Net MW drawn (consumption − generation).
    pub power_mw: f64,
    pub generated_mw: f64,
    pub consumed_mw: f64,
    pub machines: f64,
    pub footprint: f64,
    /// footprint × spacing / 64, Satisfactory only.
    pub foundations: Option<f64>,
    pub warnings: Vec<String>,
}

impl Plan {
    pub fn empty(status: PlanStatus, message: Option<String>, warnings: Vec<String>) -> Plan {
        Plan {
            status,
            message,
            lines: vec![],
            items: BTreeMap::new(),
            edges: vec![],
            power_mw: 0.0,
            generated_mw: 0.0,
            consumed_mw: 0.0,
            machines: 0.0,
            footprint: 0.0,
            foundations: None,
            warnings,
        }
    }

    pub fn item(&self, id: &str) -> PlanItem {
        self.items.get(id).cloned().unwrap_or_else(|| PlanItem {
            item: id.into(),
            ..Default::default()
        })
    }

    pub fn line(&self, id: &str) -> Option<&PlanLine> {
        self.lines.iter().find(|l| l.id == id)
    }
}
